INSERT INTO `courses` (`course_code`, `course_name`, `credits`, `section`, `class_time`, `instructor`, `category`, `description`) VALUES
('128101', 'ความรู้เบื้องต้นทางรัฐประศาสนศาสตร์ (Introduction to Public Administration)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะรัฐศาสตร์และรัฐประศาสนศาสตร์ | ความหมาย สถานภาพ และขอบข่ายของรัฐประศาสนศาสตร์ ทฤษฎีดั้งเดิมหรือแนวความคิดในยุคเก่า (ค.ศ. 1887 – 1950) ทฤษฎียุคหลังสงครามโลกครั้งที่ 2 (ค.ศ. 1950 – 1970) ทฤษฎีรัฐประศาสนศาสตร์ยุคใหม่ (ค.ศ. 1970 – ปัจจุบัน) หลักธรรมาภิบาล และจริยธรรมทางการบริหาร รัฐประศาสนศาสตร์ในบริบทการบริการราชการไทย กรณีศึกษา'),
('703100', 'พื้นฐานการสร้างธุรกิจสตาร์ทอัพและการเป็นผู้ประกอบการ (Startup and Entrepreneurship Fundamentals)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะบริหารธุรกิจ | แนวคิดของธุรกิจสตาร์ทอัพและการเป็นผู้ประกอบการ การพัฒนาแผนธุรกิจสตาร์ทอัพ กระบวนการคิดเชิงออกแบบเพื่อการพัฒนานวัตกรรม กลยุทธ์การนำผลิตภัณฑ์ออกสู่ตลาดสำหรับธุรกิจสตาร์ทอัพ กลยุทธ์การตลาดและการตลาดดิจิทัล แนวคิดการบริหารจัดการการเติบโตของธุรกิจสตาร์ทอัพ การบริหารธุรกิจครอบครัว การสร้างวัฒนธรรมองค์กรสำหรับธุรกิจสตาร์ทอัพ การใช้ข้อมูลบัญชีเพื่อการขับเคลื่อนธุรกิจสตาร์ทอัพ แนวคิดทางการเงินสำหรับการธุรกิจสตาร์ทอัพ เส้นทางการระดมทุนของธุรกิจสตาร์ทอัพ'),
('352100', 'การเกษตร อาหารท้องถิ่น และวิถีชีวิตชุมชนทางภาคเหนือ (Agriculture, Local Food and Northern Community Way of Life)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะเกษตรศาสตร์ | วัฒนธรรมและความเชื่อของการบริโภคอาหารท้องถิ่นภาคเหนือ ประเภทและชนิดของอาหารในท้องถิ่นภาคเหนือ การผลิตอาหารบนพื้นฐานทรัพยากรทางการเกษตรท้องถิ่นภาคเหนือ สรรพคุณและการใช้ประโยชน์จากอาหารท้องถิ่นภาคเหนือบนพื้นฐานทรัพยากรทางการเกษตรท้องถิ่นภาคเหนือ การส่งเสริมการบริโภคอาหารบนพื้นฐานทรัพยากรทางการเกษตรท้องถิ่นภาคเหนือ การปรุงอาหารตามภูมิปัญญาท้องถิ่นภาคเหนือ กรรมวิธีการปรุงอาหารแบบดั้งเดิมและแบบสมัยใหม่ กลยุทธ์การดึงดูดผู้บริโภคในการบริโภคอาหารท้องถิ่น กรณีศึกษา: ผู้ประกอบการที่ใช้วัตถุดิบท้องถิ่นภาคเหนือในการประกอบอาหาร'),
('026103', 'ภาษาเกาหลีในชีวิตประจำวัน 1 (Korean in Daily Life 1)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | การอ่านและการเขียนตัวอักษรเกาหลี การสนทนาภาษาเกาหลีเบื้องต้นในบริบทของสังคมและวัฒนธรรมเกาหลี'),
('140107', 'การต้านทุจริตศึกษา (Anti-corruption Studies)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะรัฐศาสตร์และรัฐประศาสนศาสตร์ | ธรรมาภิบาลในระดับโลกว่าด้วยการต้านทุจริต การต้านทุจริตกับการพัฒนาประชาธิปไตยในกระแสโลก แนวคิดพื้นฐานว่าด้วยการต่อต้านการทุจริต Strong Model ปราบทุจริตในสังคมไทย ความรู้เบื้องต้นเกี่ยวกับการประเมินคุณธรรมและความโปร่งใสในการดำเนินงาน (Integrity and Transparency Assessment : ITA) ความรู้เบื้องต้นเกี่ยวกับโครงการการปฏิบัติตามกฎระเบียบว่าด้วยการต่อต้านทุจริตในภาคธุรกิจ มาตรการการป้องกันการทุจริต กรณีศึกษาด้านการต้านทุจริตในต่างประเทศ'),
('001210', 'การพูด 1 (Oral Expression 1)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | ฝึกการสนทนาในหัวข้อที่กำหนด โดยเน้นการออกเสียงเฉพาะคำกับเสียงสูงต่ำในประโยค และฝึกแบบประโยคสนทนาเบื้องต้น'),
('003191', 'ภาษาเยอรมันสำหรับผู้เริ่มเรียน 1 (German for Beginners 1)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | สำหรับนักศึกษาที่ไม่มีพื้นความรู้ภาษาเยอรมันมาก่อน การสอนจะเน้นหนักในด้านการพูด (กระบวนวิชาเลือกสำหรับผู้เริ่มเรียน)'),
('006115', 'การตัดเย็บเสื้อผ้า 1 (Clothing Construction 1)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | การใช้และการดูแลรักษาอุปกรณ์ตัดเย็บ การวัดตัว การสร้างแบบเบื้องต้น หลักสำคัญของการตัดเย็บเสื้อผ้า การฝึกหัดปฏิบัติตัดเย็บเสื้อผ้าฝ้ายจากแบบที่สร้างไว้ การดัดแปลงแบบจากแบบตัดเบื้องต้นไปเป็นแบบอื่น ๆ'),
('006103', 'บ้านและชุมชน (Home and Community)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | ความหมาย ความสำคัญ และความสัมพันธ์ของบ้าน ครอบครัว และชุมชน สถานการณ์ปัจจุบันของครอบครัวไทย การสมรสและความสัมพันธ์ในครอบครัว การเปลี่ยนแปลงของปัจจัยที่มีผลต่อการดำเนินชีวิต ประเด็นที่เกี่ยวข้องกับชุมชนและสิ่งแวดล้อมในปัจจุบัน สถานการณ์และปัญหาครอบครัวที่มีผลกระทบต่อสังคมและชุมชน วิถีชีวิตยุคใหม่'),
('103351', 'การประพันธ์เพลง (Music Composition)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิจิตรศิลป์ | ทฤษฎีการประพันธ์เพลง องค์ประกอบดนตรี แนวคิดและเทคนิคในการประพันธ์เพลง รูปแบบในการประพันธ์เพลง และการนำเสนอผลงานการประพันธ์เพลง'),
('159151', 'สังคมและวัฒนธรรมล้านนา (Lanna Society and Culture)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะสังคมศาสตร์ | ความเป็นมาของล้านนา การก่อตัวและจุดจบของรัฐล้านนา เฮือน บ้าน และเมืองในล้านนา วัดและพุทธศาสนาในล้านนา พิธีกรรมและความเชื่อในล้านนา กลุ่มชาติพันธุ์ในล้านนา มุสลิมและชาวคริสต์ในล้านนา ภาษา ดนตรี และศิลปะในล้านนา งานป๋าเวณีในล้านนา คนเมืองหรือไทโยน ล้านนากับการเปลี่ยนแปลงยุคโลกาภิวัตน์ ล้านนากับเพื่อนบ้านลุ่มน้ำโขง'),
('008329', 'ค็อกเทลและศาสตร์การผสมเครื่องดื่ม (Cocktails and Beverage Mixology)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | พื้นฐานความรู้เกี่ยวกับเครื่องดื่มและค็อกเทล กฎหมายและความรับผิดชอบในการเสิร์ฟเครื่องดื่มแอลกอฮอล์ อุปกรณ์ บาร์และอุปกรณ์ผสมเครื่องดื่ม ชนิดของเครื่องดื่มแอลกอฮอล์ประเภทหมัก ได้แก่ เบียร์ ไวน์ ชนิดของเครื่องดื่มแอลกอฮอล์ประเภทกลั่น ได้แก่ ยิน วอดก้า รัม เตกีล่า วิสกี้ บรั่นดี ลิเคียว มิกเซอร์ การตกแต่งและนำเสนอเครื่องดื่ม ขั้นตอนการผสมเครื่องดื่มคลาสสิกค็อกเทลและค็อกเทลยุคใหม่ การบริการเครื่องดื่มแก่ลูกค้า'),
('104440', 'เครื่องปั้นดินเผาไทย (Thai Ceramics)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิจิตรศิลป์ | ลักษณะของการผลิต การใช้สอย รูปแบบ ลวดลาย อัตลักษณ์ท้องถิ่น และการตลาดของเครื่องปั้นดินเผาไทย ตั้งแต่อดีตจนถึงปัจจุบัน'),
('400110', 'เทคโนโลยีอนาคตเพื่อความมั่นคงทางอาหารของโลก (Future Technology for Global Food Security)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะเกษตรศาสตร์ | ความท้าทายด้านอาหารและสภาพอากาศ การเกษตรและการจัดการทรัพยากรธรรมชาติเพื่อความยั่งยืนทางอาหาร เทคโนโลยีและนวัตกรรมเพื่อการผลิตอาหารที่ชาญฉลาด เทคโนโลยีเพื่อความปลอดภัยทางอาหาร การค้าเกษตรและนโยบายระดับโลกที่เกี่ยวข้อง'),
('057135', 'แอโรบิคเพื่อสุขภาพ (Aerobic Exercise for Health)', 2, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะศึกษาศาสตร์ | การออกกำลังกายและการออกกำลังกายแบบแอโรบิค ประโยชน์ของการออกกำลังกายแบบแอโรบิค การออกแบบการออกกำลังกายแบบแอโรบิคเพื่อสร้างสมรรถภาพทางกาย การประเมินการออกกำลังกายแบบแอโรบิค'),
('011276', 'ปรัชญาอาหาร (Philosophy of Food)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | ความหมายของอาหาร แนวคิดทางปรัชญาเกี่ยวกับอาหาร ความสัมพันธ์ระหว่างอาหารกับมิติทางสังคมและวัฒนธรรม การวิเคราะห์มุมมองของอาหารผ่านข้อถกเถียงทางปรัชญาร่วมสมัย'),
('050106', 'ศิลปะแห่งการเป็นมนุษย์ที่มีคุณค่า (Humanistic Arts)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | การศึกษาธรรมชาติและความหมายของความเป็นมนุษย์เพื่อความเข้าใจและรู้จักตนเองและผู้อื่น มนุษย์ในสภาพแวดล้อมปัจจุบัน เป้าหมายของมนุษย์ แนวทางวิธีการหรือศิลปะที่นำไปสู่เป้าหมายของมนุษย์ ความรู้เชิงข้อเท็จจริงและเชิงคุณค่า การใช้ชีวิตและทำงานร่วมกับผู้อื่นในสังคมอย่างสันติ ด้วยมโนธรรมและสำนึกต่อสังคม'),
('900100', 'วิศวกรรมชีวการแพทย์ในชีวิตประจำวัน (Biomedical Engineering in Daily Life)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'สถาบันวิศวกรรมชีวการแพทย์ | ความเป็นมาและนิยามของวิศวกรรมชีวการแพทย์ ปัญญาประดิษฐ์และชีวสารสนเทศทางการแพทย์ สัญญาณชีวภาพ วัสดุชีวภาพ นาโนเทคโนโลยีกับการแพทย์ การแพทย์แม่นยำ การพิมพ์ 3 มิติทางชีวการแพทย์ ตลอดจนเทคโนโลยีสุขภาพเกิดใหม่อื่นๆ'),
('059419', 'การถ่ายรูปเพื่อการศึกษา (Photography in Education)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะศึกษาศาสตร์ | ทฤษฎีและหลักในการถ่ายรูป องค์ประกอบและการทำงานของกล้องถ่ายรูปประเภทต่างๆ การใช้ฟิล์ม การจัดแสง น้ำยา กลวิธีในการล้างฟิล์ม การอัดขยายภาพเพื่อเป็นอุปกรณ์การศึกษา'),
('004170', 'สังคมและวัฒนธรรมไทย (Thai Society and Culture)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | แนวทางการศึกษาสังคมและวัฒนธรรมไทย มายาคติและทัศนะครอบงำในสังคมไทย ความแตกต่างและเอกภาพของบ้านกับเมือง ภูมิปัญญาไทยที่ปรากฏในรูปพิธีกรรม ระบบอุปถัมภ์แบบไทย การต่อต้านสังคม การพึ่งตนเอง ระบบครอบครัว การสร้างความคิดนามธรรมในวัฒนธรรมไทย'),
('057127', 'แบดมินตันเพื่อชีวิตและการออกกำลังกาย (Badminton for Life and Exercise)', 1, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะศึกษาศาสตร์ | การออกกำลังกายเพื่อสุขภาพโดยการเล่นแบดมินตัน การอบอุ่นร่างกายและคลายเย็นในกีฬาแบดมินตัน การจับไม้และการเคลื่อนไหวของร่างกายเพื่อเข้าตีลูกแบดมินตันในลักษณะต่างๆ กติกาแบดมินตันทั่วไปและการนับคะแนนในกีฬาแบดมินตัน การประยุกต์เล่นกีฬาแบดมินตันในรูปแบบต่างๆ การวิเคราะห์เกมการแข่งขันแบดมินตันและการเข้าร่วมแข่งขันแบดมินตันในระดับต่างๆ ประโยชน์และมารยาทของการเป็นผู้เล่นและผู้ดูที่ดีในกีฬาแบดมินตัน'),
('204171', 'ปัญญาประดิษฐ์รอบตัวเรา (Artificial Intelligence Around Us)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิทยาศาสตร์ | ปัญญาประดิษฐ์เบื้องต้น โครงสร้างการทำงานของปัญญาประดิษฐ์ ปัญญาประดิษฐ์ในชีวิตประจำวัน ปัญญาประดิษฐ์ในบ้านอัจฉริยะ ปัญญาประดิษฐ์ในเมืองอัจฉริยะ ปัญญาประดิษฐ์ในการบันเทิงและมัลติมีเดีย ปัญญาประดิษฐ์ในภาษาศาสตร์ ปัญญาประดิษฐ์ในการเงินและชีวิตการทำงาน ปัญญาประดิษฐ์ในบริการด้านการแพทย์ ปัญญาประดิษฐ์ในการเกษตร แนวโน้ม ผลกระทบ และประเด็นทางจริยธรรมของปัญญาประดิษฐ์'),
('003101', 'ภาษาเยอรมันพื้นฐาน 1 (Fundamental German 1)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | ทักษะภาษาเยอรมันพื้นฐาน การฟัง การพูด การอ่าน การเขียน คำศัพท์และสำนวนพื้นฐาน'),
('004451', 'ประวัติศาสตร์อารมณ์ความรู้สึก (History of Emotion)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | ความสำคัญของการศึกษาประวัติศาสตร์อารมณ์ความรู้สึก และความสัมพันธ์กับการศึกษาประวัติศาสตร์ในแนวที่ใกล้เคียง เช่น ประวัติศาสตร์สังคม จุลประวัติศาสตร์ ประวัติศาสตร์ว่าด้วยจิต วิธีการศึกษาและมโนทัศน์ต่างๆ ในประวัติศาสตร์อารมณ์ความรู้สึก ความรู้สึกกับความเปลี่ยนแปลงทางสังคมและประวัติศาสตร์ ประวัติศาสตร์อารมณ์ความรู้สึกในสังคมไทย การพัฒนาแนวทางการศึกษาประวัติศาสตร์อารมณ์ความรู้สึก'),
('202100', 'ชีววิทยาในชีวิตประจำวัน (Biology in Everyday Life)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิทยาศาสตร์ | บทนำสู่ชีววิทยาในชีวิตประจำวัน ความหลากหลายทางชีวภาพ ความสำคัญและประโยชน์ของจุลินทรีย์ นิเวศวิทยาและการอยู่ร่วมกันของสิ่งมีชีวิต มลพิษสิ่งแวดล้อม ปัญหาสิ่งแวดล้อมโลกและประเทศไทย กระบวนการแบ่งเซลล์ หลักพันธุศาสตร์ โรคทางพันธุกรรม พันธุศาสตร์ประยุกต์ โภชนาการ การกินอาหาร และการย่อยอาหาร ระบบการหมุนเวียน การหายใจ การขับถ่าย การทรงตัวและการเคลื่อนไหว ระบบการประสานงานและระบบประสาท ระบบต่อมไร้ท่อและพฤติกรรมการสืบพันธุ์และการคุมกำเนิด การเจริญเติบโต'),
('204101', 'วิทยาการคอมพิวเตอร์เบื้องต้น (Introduction to Computer Science)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิทยาศาสตร์ | หลักการแก้ปัญหาด้วยคอมพิวเตอร์ ผังงาน ระบบจำนวนและการแทนข้อมูล การเขียนโปรแกรมคอมพิวเตอร์ โปรแกรมย่อย การนำเข้าและส่งออกข้อมูลจากไฟล์ขั้นพื้นฐาน ชนิดข้อมูลนามธรรม แพ็กเกจคำนวณทางวิทยาศาสตร์'),
('202130', 'แนวคิดทางชีววิทยาในสื่อ (Biological Concept in Media)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิทยาศาสตร์ | หลักการและทฤษฎีทางอณูพันธุศาสตร์หรือเทคโนโลยีชีวภาพที่เกี่ยวข้อง สื่อที่เกี่ยวกับพันธุศาสตร์หรือเทคโนโลยีชีวภาพ หลักการและทฤษฎีทางพฤติกรรมมนุษย์หรือสัตว์ สื่อที่เกี่ยวกับพฤติกรรมมนุษย์หรือสัตว์ หลักการและทฤษฎีทางภูมิคุ้มกันวิทยาหรือระบาดวิทยา สื่อที่เกี่ยวกับภูมิคุ้มกันวิทยาหรือระบาดวิทยา หลักการและทฤษฎีทางวิวัฒนาการหรือการกลายพันธุ์ สื่อที่เกี่ยวกับวิวัฒนาการหรือการกลายพันธุ์ หลักการและทฤษฎีทางภาวะโลกร้อนหรือการเปลี่ยนแปลงสภาพภูมิอากาศ สื่อที่เกี่ยวกับภาวะโลกร้อนหรือการเปลี่ยนแปลงสภาพภูมิอากาศ ประเด็นปัจจุบันทางชีววิทยาในสื่อ'),
('271113', 'เซนเซอร์และแอคชูเอเตอร์สำหรับอินเทอร์เน็ตของสรรพสิ่งในชีวิตประจำวัน (Sensors and Actuators for Internet of Things in Everyday Life)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิศวกรรมศาสตร์ | บทนำเซนเซอร์ ทรานสดิวเซอร์ และแอคชูเอเตอร์ เทคโนโลยีของเซนเซอร์ ทรานสดิวเซอร์ และแอคชูเอเตอร์ ประเภทของเซนเซอร์ ทรานสดิวเซอร์ และแอคชูเอเตอร์ที่ใช้ในชีวิตประจำวัน หลักการทำงานของเซนเซอร์ ทรานสดิวเซอร์ และแอคชูเอเตอร์ที่ใช้ในชีวิตประจำวัน การประยุกต์ใช้เซนเซอร์ ทรานสดิวเซอร์ และแอคชูเอเตอร์ในชีวิตประจำวัน ระบบอินเทอร์เน็ตของสรรพสิ่งในชีวิตประจำวัน ระบบอินเทอร์เน็ตของสรรพสิ่งและการส่งสัญญาณ อุปกรณ์อินเทอร์เน็ตของสรรพสิ่งสำหรับบ้าน (smart home) อุปกรณ์อินเทอร์เน็ตของสรรพสิ่งสำหรับการเกษตร (smart farm) การควบคุมอุปกรณ์อินเทอร์เน็ตของสรรพสิ่งและการจัดการเงื่อนไข กรณีศึกษาระบบอินเทอร์เน็ตของสรรพสิ่งในชีวิตประจำวัน'),
('031101', 'ภาษาอินโดนีเซียพื้นฐาน 1 (Fundamental Bahasa Indonesia 1)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | ลักษณะภาษาอินโดนีเซีย ระบบเสียง การอ่านและการเขียนภาษาอินโดนีเซียระดับพื้นฐาน การสนทนาในสถานการณ์ต่างๆ ในชีวิตประจำวัน'),
('031102', 'ภาษาอินโดนีเซียพื้นฐาน 2 (Fundamental Bahasa Indonesia 2)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะมนุษยศาสตร์ | การอ่านและการเขียนประโยคและย่อหน้าขนาดสั้น การสนทนาภาษาอินโดนีเซียในสถานการณ์ต่างๆ ในชีวิตประจำวัน (เงื่อนไข: ผ่านวิชา 031101 หรือได้รับความยินยอมจากภาควิชา)'),
('176104', 'สิทธิและหน้าที่พลเมืองในยุคดิจิทัล (Rights and Duties of Citizen in Digital Age)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะนิติศาสตร์ | สิทธิและหน้าที่ของพลเมืองในยุคดิจิทัลอันเนื่องมาจากกฎหมายควบคุมกิจกรรมของบุคคลและนิติบุคคลในพื้นที่ไซเบอร์ การนำกฎหมายมาปรับใช้กับกิจกรรมที่เชื่อมโยงกับโลกไซเบอร์ ความสัมพันธ์ระหว่างกิจกรรมในพื้นที่ไซเบอร์และผลทางกฎหมายในโลกจริง การใช้สิทธิและปฏิบัติตามหน้าที่อันเนื่องมาจากนิติกรรมและนิติเหตุทั้งในแง่มหาชนและเอกชน อาทิ สิทธิเสรีภาพในยุคดิจิทัล อาชญากรรมไซเบอร์ ระบบกรรมสิทธิ์เนื้อหาในโลกดิจิทัล สัญญาออนไลน์และการคุ้มครองผู้บริโภค และความรับผิดของผู้ให้บริการและควบคุมระบบ (สำหรับนักศึกษานอกสาขาวิชา)'),
('271111', 'หุ่นยนต์วิจักษ์ (Robotics Appreciation)', 3, '', '', '', 'หมวดวิชาเลือกเสรี', 'คณะวิศวกรรมศาสตร์ | ประวัติของหุ่นยนต์และอุตสาหกรรมหุ่นยนต์ ภาพรวมของเทคโนโลยีหุ่นยนต์ การจำแนกประเภทของหุ่นยนต์ ส่วนประกอบและลักษณะของหุ่นยนต์ แนวคิดในการพัฒนาหุ่นยนต์ การประยุกต์หุ่นยนต์ ผลกระทบของหุ่นยนต์ต่อการดำรงชีวิตในสังคมโลก ผลกระทบของหุ่นยนต์ต่ออุตสาหกรรมโลก แนวโน้มการวิจัยและพัฒนาหุ่นยนต์ กรณีศึกษาหุ่นยนต์ในประเทศไทย');
